class Solution {
    func wordBreak(_ s: String, _ wordDict: [String]) -> Bool {
        let chars = Array(s)

        func dfs(_ i: Int) -> Bool {
            if i == chars.count {
                return true
            }

            for w in wordDict {
                if i + w.count <= chars.count,
                   String(chars[i..<i + w.count]) == w {
                    if dfs(i + w.count) {
                        return true
                    }
                }
            }
            return false
        }

        return dfs(0)
    }
