impl Solution {
    pub fn word_break(s: String, word_dict: Vec<String>) -> bool {
        let n = s.len();
        let mut memo = HashMap::new();
        memo.insert(n, true);

        fn dfs(
            s: &[u8], word_dict: &[String], i: usize,
            memo: &mut HashMap<usize, bool>,
