                let wb = w.as_bytes();
                if i + wb.len() <= s.len() && &s[i..i + wb.len()] == wb {
                    if dfs(s, word_dict, i + wb.len(), memo) {
                        memo.insert(i, true);
                        return true;
                    }
                }
            }
            memo.insert(i, false);
            false
        }

        dfs(s.as_bytes(), &word_dict, 0, &mut memo)
    }
